/**
 * The table of suffix LCS lengths: `table[i][j]` is the length of the longest
 * common subsequence of `base.slice(i)` and `side.slice(j)`.
 */
function suffixLcsTable(base, side) {
  const n = base.length
  const m = side.length
  const table = new Array(n + 1)
  for (let i = n; i >= 0; i -= 1) {
    table[i] = new Int32Array(m + 1)
  }
  for (let i = n - 1; i >= 0; i -= 1) {
    const row = table[i]
    const next = table[i + 1]
    for (let j = m - 1; j >= 0; j -= 1) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }
  return table
}

