 * The matched line pairs of the earliest longest common subsequence: walking
 * both documents from the start, a match is taken whenever the two current
 * lines are equal, and otherwise the side whose remaining subsequence is at
 * least as long as the other's advances, the base winning ties.
 */
function matchPairs(base, side) {
  const table = suffixLcsTable(base, side)
  const pairs = []
  let i = 0
  let j = 0
  while (i < base.length && j < side.length) {
    if (base[i] === side[j]) {
      pairs.push([i, j])
      i += 1
      j += 1
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return pairs
