{"file_path":"src/merge.js","content":"/**
 * The three-way merge itself: the changes of both sides against the base are
 * gathered into regions, and every region is resolved or declared a conflict.
 */

import { diffChanges } from './diff.js'

/**
 * The changes of both sides in one list, ordered by where they start in the
 * base, mine's changes coming first when two changes start at the same place.
 */
function gatherChanges(mine, base, theirs) {
  const all = []
  for (const change of diffChanges(base, mine)) all.push({ ...change, side: 'mine' })
  for (const change of diffChanges(base, theirs)) all.push({ ...change, side: 'theirs' })
  return all
    .map((change, order) => ({ change, order }))
    .sort((a, b) => {
      if (a.change.baseStart !== b.change.baseStart) return a.change.baseStart - b.change.baseStart
      if (a.change.side !== b.change.side) return a.change.side === 'mine' ? -1 : 1
      return a.order - b.order
    })
    .map(entry => entry.change)
}

/**
 * The overlapping groups of changes: the first remaining change opens a region
 * running from its base start to its base end, and each following change is
 * absorbed while it starts at or before the region's current end.
 */
function groupChanges(changes) {
  const groups = []
  let group = null
  for (const change of changes) {
    if (group !== null && change.baseStart <= group.baseEnd) {
      group.changes.push(change)
      if (change.baseEnd > group.baseEnd) group.baseEnd = change.baseEnd
    } else {
      group = { baseStart: change.baseStart, baseEnd: change.baseEnd, changes: [change] }
      groups.push(group)
    }
  }
  return groups
}

/**
 * One side's lines for a region: the base lines when that side left the region
 * alone, and otherwise its own replacement, running from the smallest start of
 * its changes moved back by however far the region begins before them, to the
 * largest end of its changes moved forward by however far the region ends
 * after them.
 */
function sideLines(group, side, document, base) {
  const changes = group.changes.filter(change => change.side === side)
  if (changes.length === 0) return base.slice(group.baseStart, group.baseEnd)
  let first = changes[0]
  let last = changes[0]
  for (const change of changes) {
    if (change.baseStart < first.baseStart) first = change
    if (change.baseEnd > last.baseEnd) last = change
  }
  const start = first.sideStart - (first.baseStart - group.baseStart)
  const end = last.sideEnd + (group.baseEnd - last.baseEnd)
  return document.slice(start, end)
}

const equalLines = (left, right) =>
  left.length === right.length && left.every((line, index) => line === right[index])

