 * The regions of the merge in order: the stable stretches of base lines the
 * merge keeps unchanged, and the changed regions, each resolved to one side's
 * lines or reported as a conflict. Empty stable stretches are left out.
 */
export function mergeRegions(mine, base, theirs) {
  const regions = []
  let at = 0
  const stableUpTo = end => {
    if (end > at) regions.push({ kind: 'stable', lines: base.slice(at, end) })
    at = end
  }
  for (const group of groupChanges(gatherChanges(mine, base, theirs))) {
    stableUpTo(group.baseStart)
